{
  "query": "adversarial benchmark machine learning fairness",
  "results": [
    {
      "paperId": "e8190682632938458fbf4a386dd6f26dbaa63032",
      "title": "Approaching Machine Learning Fairness through Adversarial Network",
      "abstract": "Fairness is becoming a rising concern w.r.t. machine learning model performance. Especially for sensitive fields such as criminal justice and loan decision, eliminating the prediction discrimination towards a certain group of population (characterized by sensitive features like race and gender) is important for enhancing the trustworthiness of model. In this paper, we present a new general framework to improve machine learning fairness. The goal of our model is to minimize the influence of sensitive feature from the perspectives of both the data input and the predictive model. In order to achieve this goal, we reformulate the data input by removing the sensitive information and strengthen model fairness by minimizing the marginal contribution of the sensitive feature. We propose to learn the non-sensitive input via sampling among features and design an adversarial network to minimize the dependence between the reformulated input and the sensitive information. Extensive experiments on three benchmark datasets suggest that our model achieve better results than related state-of-the-art methods with respect to both fairness metrics and prediction performance.",
      "authors": [
        {
          "name": "Xiaoqian Wang",
          "authorId": "47120784"
        },
        {
          "name": "Heng Huang",
          "authorId": "145114933"
        }
      ],
      "year": 2019,
      "venue": "arXiv.org",
      "citationCount": 8,
      "referenceCount": 16,
      "url": "https://www.semanticscholar.org/paper/e8190682632938458fbf4a386dd6f26dbaa63032"
    },
    {
      "paperId": "f0861ef39a7a767e279a6e03eecda9fa8e9e77e4",
      "title": "A Benchmark Proposal for Non‐Generative Fair Adversarial Learning Strategies Using a Fairness‐Utility Trade‐off Metric",
      "abstract": "AI systems for decision‐making have become increasingly popular in several areas. However, it is possible to identify biased decisions in many applications, which have become a concern for the computer science, artificial intelligence, and law communities. Therefore, researchers are proposing solutions to mitigate bias and discrimination among decision‐makers. Some explored strategies are based on GANs to generate fair data. Others are based on adversarial learning to achieve fairness by encoding fairness constraints through an adversarial model. Moreover, it is usual for each proposal to assess its model with a specific metric, making comparing current approaches a complex task. Therefore, this work proposes a systematical benchmark procedure to assess the fair machine learning models. The proposed procedure comprises a fairness‐utility trade‐off metric ( FU‐score$$ FU\\hbox{-} score $$ ), the utility and fairness metrics to compose this assessment, the used datasets and preparation, and the statistical test. A previous work presents some of these definitions. The present work enriches the procedure by increasing the applied datasets and statistical guarantees when comparing the models' results. We performed this benchmark evaluation for the non‐generative adversarial models, analyzing the literature models from the same metric perspective. This assessment could not indicate a single model which better performs for all datasets. However, we built an understanding of how each model performs on each dataset with statistical confidence.",
      "authors": [
        {
          "name": "L. D. de Lima",
          "authorId": "2244413206"
        },
        {
          "name": "D. R. Ricarte",
          "authorId": "2307340255"
        },
        {
          "name": "Clauirton A. Siebra",
          "authorId": "2273974569"
        }
      ],
      "year": 2024,
      "venue": "International Conference on Climate Informatics",
      "citationCount": 2,
      "referenceCount": 31,
      "url": "https://www.semanticscholar.org/paper/f0861ef39a7a767e279a6e03eecda9fa8e9e77e4"
    },
    {
      "paperId": "00081a406abfcb678095a81c3fc914562016a226",
      "title": "Fairness-Aware Machine Learning Framework for Bias Mitigation in Large-Scale Data Analytics",
      "abstract": "The paper presents a fairness-conscious machine learning system as a systematic process of identifying, estimating, and addressing bias in data analytics systems on large data sets. The three strategies are proposed to be combined into a single framework, fairness-regularised objective function, which penalises disparate impact in model training, adversarial debiasing module, which learns to decorrelate predictions by protected attributes, and adaptive instance reweighting mechanism, which dynamically reassigns importance to samples according to subgroup-specific error rates. Our framework, as evidenced by extensive experiments on five benchmark datasets that include income prediction, recidivism assessment, credit scoring, facial attribute classification, and clinical outcome prediction, decreases the statistical parity difference between our framework and unconstrained baselines by 78.4 per cent and decreases the equalised odds difference by 80.5 per cent whilst maintaining 99.4 per cent of the original predictive accuracy. Moreover, we include a scaling analysis that proves sub-linear growth in the number of computational overheads with the increased datasets of over five million records. The framework offers practitioners interpretable fairness diagnostics and adjustable trade-off parameters, creating a viable basis of responsible AI use in enterprise data analytics systems.",
      "authors": [
        {
          "name": "Shreekant Salotagi",
          "authorId": "2164903309"
        },
        {
          "name": "T. Sardar",
          "authorId": "31307724"
        },
        {
          "name": "D. Pal",
          "authorId": "2350818397"
        },
        {
          "name": "Madhumala R. B.",
          "authorId": "2209312462"
        },
        {
          "name": "S. Hole",
          "authorId": "2156278437"
        },
        {
          "name": "Sridhar S. K.",
          "authorId": "2386560282"
        }
      ],
      "year": 2026,
      "venue": "2026 9th International Conference on Trends in Electronics and Informatics (ICOEI)",
      "citationCount": 0,
      "referenceCount": 21,
      "url": "https://www.semanticscholar.org/paper/00081a406abfcb678095a81c3fc914562016a226"
    },
    {
      "paperId": "e8edfc06f8003659c8f8112e59af4ef404df35bd",
      "title": "Adversarial Bias: Data Poisoning Attacks on Fairness",
      "abstract": "With the growing adoption of AI and machine learning systems in real-world applications, ensuring their fairness has become increasingly critical. In this work, we first provide a theoretical analysis demonstrating that a simple adversarial poisoning strategy is sufficient to induce maximally unfair behavior in naive Bayes classifiers. Our key idea is to strategically inject a small fraction of carefully-crafted adversarial data points into the training set, biasing the model's decision boundary to disproportionately affect a protected group while preserving generalizable performance. To illustrate the practical effectiveness of our method, we conduct experiments across three benchmark datasets and models. We find that our attack significantly outperforms existing methods in degrading fairness metrics across multiple models and datasets, often achieving substantially higher levels of unfairness with a comparable or only slightly worse impact on accuracy. Notably, our method proves effective on a wide range of models, in contrast to prior work, demonstrating a robust and potent approach to compromising the fairness of machine learning systems.",
      "authors": [
        {
          "name": "Eunice Chan",
          "authorId": "2235777469"
        },
        {
          "name": "Hanghang Tong",
          "authorId": "2256983432"
        }
      ],
      "year": 2025,
      "venue": "BigData Congress [Services Society]",
      "citationCount": 0,
      "referenceCount": 23,
      "url": "https://www.semanticscholar.org/paper/e8edfc06f8003659c8f8112e59af4ef404df35bd"
    },
    {
      "paperId": "ac9f1a78652da2d5f0b6e2ad39d83bc3fab30afe",
      "title": "A Novel Machine Learning Framework for Detecting and Correcting Gender Bias in Predictive Models",
      "abstract": "Machine learning models increasingly influence high-stakes decision-making, yet they often inherit and amplify gender bias from underlying data. This study proposes a novel Fairness-Guided Gender Bias Mitigation Framework (FG-GBMF) for detecting and correcting gender bias in predictive models. The proposed methodology integrates data-level bias auditing, model-level interpretability analysis, and a hybrid debiasing strategy that combines reweighting with adversarial learning. A fairness–performance optimization layer is incorporated to balance equity objectives with predictive accuracy. Experimental evaluations conducted on benchmark datasets demonstrate that FG-GBMF significantly reduces gender-based disparities while preserving model effectiveness. The results highlight the robustness and adaptability of the proposed framework, supporting its applicability in developing transparent, ethical, and gender-fair machine learning systems.",
      "authors": [
        {
          "name": "Punitha K",
          "authorId": "2188274790"
        },
        {
          "name": "Sasirekha R",
          "authorId": "2350323666"
        },
        {
          "name": "T. K",
          "authorId": "2284888957"
        },
        {
          "name": "Mangairkarasi S",
          "authorId": "2434456555"
        },
