      "year": 2026,
      "venue": "International Congress on Information and Communication Technology",
      "citationCount": 0,
      "referenceCount": 19,
      "url": "https://www.semanticscholar.org/paper/ac9f1a78652da2d5f0b6e2ad39d83bc3fab30afe"
